// ********************** GOOGLE CLOUD STORAGE **********************

/** Config key holding the bucket where documents are stored on Google Cloud Storage. */
public static final String GOOGLE_BUCKET_CONFIG_KEY = "google.storage.bucket.name"
/** Config key holding the classpath location of the service account resource supplied by the runtime. */
public static final String GOOGLE_CREDENTIALS_CONFIG_KEY = "google.storage.credentials.resource"
private static final String DEFAULT_GOOGLE_BUCKET_NAME = "bank-scraper-documents"
private static final String DEFAULT_GOOGLE_CREDENTIALS_RESOURCE = "google-service-account.json"

/**
 * Reads a setting from the application config, falling back to a system property, an environment
 * variable and finally the given default. Kept lenient on purpose so that the storage helpers stay
 * usable when no Grails config is bound to the current thread.
 */
private static String fetchStorageSetting(String key, String defaultValue) {
    String value = null
    try {
        def configuredValue = Holders.getFlatConfig()?.get(key)
        value = configuredValue ? configuredValue.toString() : null
    } catch (Throwable t) {
        log.debug("=== Unable to read '${key}' from application config ===>>> ${t.message}")
    }
    if (StringUtils.isBlank(value))
        value = System.getProperty(key)
    if (StringUtils.isBlank(value))
        value = System.getenv(key.toUpperCase().replaceAll("[^A-Z0-9]", "_"))
    StringUtils.isNotBlank(value) ? value : defaultValue
}

public static String fetchGoogleBucketName() {
    fetchStorageSetting(GOOGLE_BUCKET_CONFIG_KEY, DEFAULT_GOOGLE_BUCKET_NAME)
}

/**
 * Builds the Google Cloud Storage service. The deployed runtime ships its service account resource on
 * the classpath, so it is picked up from there when available, otherwise the ambient (application
 * default) credentials of the environment are used.
 */
private static Storage fetchGoogleStorageService() {
    Storage storage = null
    String credentialsResource = fetchStorageSetting(GOOGLE_CREDENTIALS_CONFIG_KEY, DEFAULT_GOOGLE_CREDENTIALS_RESOURCE)
    InputStream credentialsStream = HelperMethod.class.classLoader.getResourceAsStream(credentialsResource)
    if (credentialsStream) {
        try {
            storage = StorageOptions.newBuilder()
                    .setCredentials(GoogleCredentials.fromStream(credentialsStream))
                    .build()
                    .getService()
        } catch (Throwable t) {
            log.error("Exception while building Google Cloud Storage service using '${credentialsResource}' ==>> ${t.message}", t)
        } finally {
            credentialsStream.close()
        }
    }
    if (!storage) {
        try {
            storage = StorageOptions.newBuilder().build().getService()
        } catch (Throwable t) {
            log.debug("=== Falling back on default Google Cloud Storage options ===>>> ${t.message}")
        }
    }
    if (!storage)
        storage = StorageOptions.getDefaultInstance().getService()
    storage
}

public static Boolean uploadObjectToGoogleCloudStorage(File file, String path) {
    Boolean isFileUploaded = Boolean.FALSE
    if (path) {
        try {
            Storage storage = fetchGoogleStorageService()
            BlobInfo blobInfo = BlobInfo.newBuilder(fetchGoogleBucketName(), path).build()
            storage.create(blobInfo, file.bytes)
            isFileUploaded = Boolean.TRUE
        }
        catch (Exception e) {
            log.error("Exception while uploading file to Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    isFileUploaded
}

public static InputStream downloadObjectFromGoogleCloudStorage(String path) {
    InputStream inputStream = null
    if (path) {
        try {
            Storage storage = fetchGoogleStorageService()
            byte[] contents = fetchGoogleObjectContents(storage, fetchGoogleBucketName(), path)
            if (contents != null)
                inputStream = new ByteArrayInputStream(contents)
        }
        catch (Exception e) {
            log.error("Exception while downloading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    inputStream
}

private static byte[] fetchGoogleObjectContents(Storage storage, String bucketName, String path) {
    byte[] contents = null
    try {
        def blob = storage.get(bucketName, path)
        if (blob)
            contents = blob.getContent()
    } catch (Exception e) {
        log.debug("=== Unable to read blob '${path}' from bucket '${bucketName}' ===>>> ${e.message}")
    }
    if (contents == null) {
        try {
            contents = storage.readAllBytes(bucketName, path)
        } catch (Exception e) {
            log.error("Exception while reading file from Google Cloud Storage ==>> ${e.message}", e)
        }
    }
    contents
}

public static void uploadObjectToLocalOrGoogleCloudStorage(File pdfFile, String documentPath = null) {
    if (GrailsUtil.developmentEnv) {
        log.info("=== Requesting file to be uploaded on Local location ===>>> ${documentPath}")
        File file = new File(documentPath)
        FileUtils.writeByteArrayToFile(file, pdfFile.getBytes())
    } else {
        log.info("=== Requesting file to be uploaded on Google Cloud Storage location ===>>> ${documentPath}")
        uploadObjectToGoogleCloudStorage(pdfFile, documentPath)
    }
}

// Short hand names for the Google Cloud Storage helpers above.

public static Boolean uploadObjectToGoogle(File file, String path) {
    uploadObjectToGoogleCloudStorage(file, path)
}

public static InputStream downloadObjectFromGoogle(String path) {
    downloadObjectFromGoogleCloudStorage(path)
}

public static void uploadObjectToLocalOrGoogle(File pdfFile, String documentPath = null) {
    uploadObjectToLocalOrGoogleCloudStorage(pdfFile, documentPath)
}

public static InputStream downloadObjectFromLocalOrS3OrAzureOrGoogle(com.bankScraper.bank.Document document) {
    downloadObjectFromLocalOrS3OrAzure(document)
}

