package com.google.cloud.storage

class BlobInfo {
    String bucket
    String name
    static Builder newBuilder(String bucket, String name) { new Builder(bucket: bucket, name: name) }
    static class Builder {
        String bucket
        String name
        BlobInfo build() { new BlobInfo(bucket: bucket, name: name) }
    }
