class Blob {
    String bucket
    String name
    byte[] data
    byte[] getContent() { data }
}

interface Storage {
    Blob create(BlobInfo info, byte[] bytes)
    Blob get(String bucket, String name)
    byte[] readAllBytes(String bucket, String name)
}

class InMemoryStorage implements Storage {
    static Map<String, Blob> blobs = [:]
    static List<String> events = []
    Blob create(BlobInfo info, byte[] bytes) {
        events << "create:${info.bucket}:${info.name}:${bytes.length}"
        Blob b = new Blob(bucket: info.bucket, name: info.name, data: bytes)
        blobs["${info.bucket}/${info.name}"] = b
        b
    }
    Blob get(String bucket, String name) { blobs["${bucket}/${name}"] }
    byte[] readAllBytes(String bucket, String name) {
        Blob b = blobs["${bucket}/${name}"]
        if (!b) throw new RuntimeException("no such object")
        b.data
    }
}

class StorageOptions {
    static Builder newBuilder() { new Builder() }
    static StorageOptions getDefaultInstance() { new StorageOptions() }
    Storage getService() { new InMemoryStorage() }
    static class Builder {
        Builder setCredentials(def credentials) { this }
        StorageOptions build() { new StorageOptions() }
    }
}
