/** Classpath locations the runtime is allowed to drop its service account resource at. */
private static final List<String> GOOGLE_CREDENTIALS_RESOURCES = ["google-service-account.json",
                                                                 "google-credentials.json",
                                                                 "service-account.json"]

/**
 * Locates the service account resource shipped with the deployed runtime. Nothing is read from the
 * repository itself, the resource only ever lives on the classpath of the deployed application.
 */
private static InputStream fetchGoogleCredentialsStream() {
    List<String> resources = []
    String configuredResource = fetchStorageSetting(GOOGLE_CREDENTIALS_CONFIG_KEY, null)
    if (StringUtils.isNotBlank(configuredResource))
        resources << configuredResource
    resources.addAll(GOOGLE_CREDENTIALS_RESOURCES)
    InputStream credentialsStream = null
    for (String resource : resources) {
        credentialsStream = HelperMethod.class.classLoader.getResourceAsStream(resource)
        if (credentialsStream) {
            log.debug("=== Using Google service account resource ===>>> ${resource}")
            break
        }
    }
    credentialsStream
}

/**
 * Builds the Google Cloud Storage service. The deployed runtime ships its service account resource on
 * the classpath, so it is used whenever it can be found, otherwise the credentials configured for the
 * environment itself are used.
 */
private static Storage fetchGoogleStorageService() {
    Storage storage = null
    InputStream credentialsStream = fetchGoogleCredentialsStream()
    if (credentialsStream) {
        try {
            storage = StorageOptions.newBuilder()
                    .setCredentials(GoogleCredentials.fromStream(credentialsStream))
                    .build()
                    .getService()
        } catch (Throwable t) {
            log.error("Exception while building Google Cloud Storage service from the service account resource ==>> ${t.message}", t)
        } finally {
            credentialsStream.close()
        }
    }
    if (!storage)
        storage = StorageOptions.getDefaultInstance().getService()
    storage
}

